        if (unit.listingPurpose !== 'rent' && !unit.salePrice.trim())
          issues.push(`${label}: ${t('PropertyForm.salePrice')}`);
      });
    }
  }
  if (index === 4) {
    // Images are optional so save can proceed when media upload is degraded.
