import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';

const dir = 'docs/handoffs/2026-08-31-evening-continue-tomorrow';
const src =
  'C:/Users/ameed/.cursor/projects/c-dev-BHD-R/agent-transcripts/307d3b18-d433-4130-9cd4-fbf9f887f158/307d3b18-d433-4130-9cd4-fbf9f887f158.jsonl';
const jsonlOut = path.join(dir, 'conversation-transcript-FULL.jsonl');
const mdOut = path.join(dir, 'conversation-readable-FULL.md');

fs.mkdirSync(dir, { recursive: true });
fs.copyFileSync(src, jsonlOut);
const buf = fs.readFileSync(jsonlOut);
const sha = crypto.createHash('sha256').update(buf).digest('hex');
const lines = buf.toString('utf8').split(/\r?\n/).filter(Boolean);

const md = [];
md.push('# نسخة مقروءة كاملة من محادثة Cursor');
md.push('');
md.push('- **المصدر:** conversation-transcript-FULL.jsonl (نسخة حرفية)');
md.push('- **تاريخ التوثيق:** 2026-08-31');
md.push('- **وقت التوثيق (مسقط / UTC+4):** 22:43');
md.push('- **معرّف المحادثة:** 307d3b18-d433-4130-9cd4-fbf9f887f158');
md.push(`- **عدد أسطر JSONL:** ${lines.length}`);
md.push(`- **SHA256:** \`${sha}\``);
md.push('');
md.push('> استخراج نصوص المستخدم/المساعد دون حذف محتوى نصي داخل الرسائل.');
md.push('');

let i = 0;
for (const line of lines) {
  let ev;
  try {
    ev = JSON.parse(line);
  } catch {
    continue;
  }
  const role = ev.role || ev.message?.role || 'unknown';
  const msg = ev.message || ev;
  const content = msg.content;
  const texts = [];
  if (typeof content === 'string') texts.push(content);
  else if (Array.isArray(content)) {
    for (const part of content) {
      if (!part) continue;
      if (typeof part === 'string') texts.push(part);
      else if (part.type === 'text' && typeof part.text === 'string') texts.push(part.text);
      else if (part.type === 'image' || part.type === 'image_url') texts.push('[صورة مرفقة في المحادثة]');
      else if (part.type === 'tool_use') texts.push(`[tool_use: ${part.name || ''}]`);
      else if (part.type === 'tool_result') texts.push('[tool_result]');
    }
  }
  if (!texts.length) continue;
  i += 1;
  const title = role === 'user' ? 'المستخدم' : role === 'assistant' ? 'المساعد' : role;
  md.push('---');
  md.push('');
  md.push(`## ${i}. ${title}`);
  md.push('');
  md.push(texts.join('\n\n'));
  md.push('');
}

fs.writeFileSync(mdOut, md.join('\n'), 'utf8');
fs.writeFileSync(
  path.join(dir, 'MANIFEST.md'),
  [
    '# MANIFEST — تسليم مسائي 2026-08-31 22:43 (مسقط)',
    '',
