    '',
    `**SHA256 لـ JSONL:** \`${sha}\``,
    '',
    `**رسائل مستخرجة:** ${i}`,
    '',
  ].join('\n'),
  'utf8',
);
console.log(JSON.stringify({ sha, lines: lines.length, messages: i, bytes: buf.length }));

